+// L3-023 Accessibility Polish Application - app.js
+(function() {
+  'use strict';
+
+  // --- State Management (localStorage) ---
+  const STORAGE_KEY = 'l3-023-app-state';
+  
+  function loadState() {
+    try {
+      const raw = localStorage.getItem(STORAGE_KEY);
+      return raw ? JSON.parse(raw) : { count: 0, theme: 'light' };
+    } catch (e) {
+      console.warn('Failed to load state:', e);
+      return { count: 0, theme: 'light' };
+    }
+  }
+
+  function saveState(state) {
+    try {
+      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
+    } catch (e) {
+      console.warn('Failed to save state:', e);
+    }
+  }
+
+  let state = loadState();
+
+  // --- DOM Elements ---
+  const countDisplay = document.getElementById('count-display');
+  const themeToggle = document.getElementById('theme-toggle');
+  const resetBtn = document.getElementById('reset-btn');
+  const statusMsg = document.getElementById('status-msg');
+  const mainContent = document.getElementById('main-content');
+
+  // --- Accessibility Utilities ---
+  function announce(message) {
+    if (statusMsg) {
+      statusMsg.textContent = message;
+      // Clear timeout if exists to prevent stacking
+      clearTimeout(window.announceTimeout);
+      window.announceTimeout = setTimeout(() => {
+        statusMsg.textContent = '';
+      }, 5000);
+    }
+  }
+
+  function handleKeyNav(e) {
+    // Announce when Tab is pressed to inform screen readers of focus changes
+    if (e.key === 'Tab') {
+      const focusedEl = document.activeElement;
+      announce(`${focusedEl.tagName} focused: ${focusedEl.textContent || ''}`);
+    }
+  }
+
+  // --- Event Listeners ---
+  
+  // Theme Toggle
+  themeToggle.addEventListener('click', () => {
+    state.theme = state.theme === 'light' ? 'dark' : 'light';
+    document.body.setAttribute('data-theme', state.theme);
+    saveState(state);
+    announce(`Theme changed to ${state.theme} mode`);
+  });
+
+  // Counter Increment
+  mainContent.addEventListener('click', (e) => {
+    if (e.target === mainContent || e.target.id === 'increment-btn') {
+      state.count++;
+      countDisplay.textContent = `Count: ${state.count}`;
+      saveState(state);
+      announce(`Count incremented to ${state.count}`);
+    }
+  });
+
+  // Reset
+  resetBtn.addEventListener('click', () => {
+    if (confirm('Reset application data?')) {
+      state.count = 0;
+      countDisplay.textContent = `Count: ${state.count}`;
+      saveState(state);
+      announce('Application data reset');
+    }
+  });
+
+  // Global Key Navigation Handler
+  document.addEventListener('keydown', handleKeyNav);
+
+  // --- Initialization ---
+  function init() {
+    // Apply saved theme
+    document.body.setAttribute('data-theme', state.theme);
+    
+    // Initial announcement for screen readers
+    announce(`Welcome to L3-023 App. Current count is ${state.count}. Theme is ${state.theme}.`);
+    
+    // Ensure focus is on the main content area for keyboard users
+    mainContent.focus();
+  }
+
+  init();
+})();

